sys_script_include.script:
var getAssignment = Class.create();
getAssignment.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


    //receive the user name from the disctionary override
    //filters the group based on that and stores in an aray

    nameGroup: function(username) {
        if (username) {

            var storeGroup = [];
            var grmember = new GlideRecord('sys_user_grmember');
            grmember.addQuery('user', username);
            grmember.query();

            while (grmember.next()) {
                storeGroup.push(grmember.getValue('group'));
            }

            //script include always return string
            return 'sys_idIN' + storeGroup.toString();
        }
    },

    type: 'getAssignment'
});
